import functools
import time

def retry(func):
    """
    A decorator that retries a function up to 3 times if an exception occurs.

    Args:
        func (callable): The function to be decorated.

    Returns:
        callable: The wrapped function with retry logic.
    """
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        max_attempts = 3
        last_exception = None

        for attempt in range(1, max_attempts + 1):
            try:
                return func(*args, **kwargs)
            except Exception as e:
                last_exception = e
                print(f"Attempt {attempt} failed: {e}")
                if attempt < max_attempts:
                    print("Retrying...")
                else:
                    print("All attempts failed.")

        # If all attempts are exhausted, raise the last caught exception
        raise last_exception

    return wrapper

# --- Testing the decorator ---

if __name__ == "__main__":
    # Test Case 1: A function that fails twice and then succeeds
    # We use a mutable dictionary to track calls across function invocations
    call_tracker = {"count": 0}

    @retry
    def flaky_function():
        call_tracker["count"] += 1
        if call_tracker["count"] < 3:
            raise ValueError("Temporary error occurred!")
        return "Success on attempt 3!"

